import{_ as e,o as a,c as d,a3 as s}from"./chunks/framework.BUxR7uXn.js";const u=JSON.parse('{"title":"UE 半透明渲染（4.27 Deferred）","description":"","frontmatter":{},"headers":[],"relativePath":"Unreal Engine/半透明渲染.md","filePath":"Unreal Engine/半透明渲染.md","lastUpdated":null}'),n={name:"Unreal Engine/半透明渲染.md"};function r(o,t,c,l,p,i){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="ue-半透明渲染-4-27-deferred" tabindex="-1">UE 半透明渲染（4.27 Deferred） <a class="header-anchor" href="#ue-半透明渲染-4-27-deferred" aria-label="Permalink to &quot;UE 半透明渲染（4.27 Deferred）&quot;">​</a></h1><p>本文讨论 <strong>UE 4.27.2 桌面 Deferred 管线中的常规光栅半透明路径</strong>。Mobile、光线追踪半透明和后续 UE5 版本有各自的实现，不能直接套用这里的 Pass 与排序结论。</p><p>通用的 Alpha 混合、深度写入和交叉排序原理见 <a href="./../图形学/透明渲染.html">透明渲染</a>。本文重点解释这些原理在 UE 中如何落实：<strong>材质决定混合方式和光照方式，可见性阶段决定进入哪些 MeshPass，各 Pass 分别排序、绘制，最后按约定合成到场景。</strong></p><h2 id="_1-先看半透明在一帧中的位置" tabindex="-1">1. 先看半透明在一帧中的位置 <a class="header-anchor" href="#_1-先看半透明在一帧中的位置" aria-label="Permalink to &quot;1. 先看半透明在一帧中的位置&quot;">​</a></h2><p>UE 的 Deferred 管线并不是所有物体都走延迟光照。常规半透明不把自己的多层表面写进不透明 GBuffer，而是在不透明场景已经完成光照后，用透明材质自己的 Shader 着色并合成。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不透明 / Masked 几何</span></span>
<span class="line"><span>    -&gt; GBuffer 与不透明深度</span></span>
<span class="line"><span>    -&gt; 延迟光照，准备半透明光照体积</span></span>
<span class="line"><span>    -&gt; 大气、雾等场景处理</span></span>
<span class="line"><span>    -&gt; 绘制半透明</span></span>
<span class="line"><span>         Standard：通常直接混入 SceneColor</span></span>
<span class="line"><span>         AfterDOF：写独立颜色缓冲，暂不混入 SceneColor</span></span>
<span class="line"><span>         AfterDOFModulate：写独立滤色缓冲</span></span>
<span class="line"><span>    -&gt; 后续 Distortion、透明速度等相关 Pass（按配置执行）</span></span>
<span class="line"><span>    -&gt; 后处理：对 SceneColor 做景深，并在相应阶段合成独立半透明</span></span></code></pre></div><p>这是理解主路径的简化顺序。水下半透明等特殊路径会提前到 SingleLayerWater 之前；完整帧结构见 <a href="./UE基础渲染管线.html">UE基础渲染管线</a>。</p><p><strong>AfterDOF 主要描述合成时机，不等于所有透明几何都等到景深结束后才开始绘制。</strong> 几何可以先画到独立 RT，等背景完成景深后再合成。</p><p>透明颜色 Pass 通常开启深度测试、关闭深度写入：用不透明深度挡住墙后的透明片元，同时允许多层透明贡献颜色。UE 常用比较函数 <code>CF_DepthNearOrEqual</code>；启用材质的 <code>Disable Depth Test</code> 后可改为 <code>CF_Always</code>，也就失去了这层不透明遮挡。Custom Depth、速度等额外 Pass 需要分别看自己的状态。</p><p>关于 GBuffer 为什么不能直接混合透明材质，见 <a href="./../图形学/透明渲染.html#延迟渲染如何处理半透明">延迟渲染如何处理半透明</a>。</p><h2 id="_2-材质先决定怎样混合" tabindex="-1">2. 材质先决定怎样混合 <a class="header-anchor" href="#_2-材质先决定怎样混合" aria-label="Permalink to &quot;2. 材质先决定怎样混合&quot;">​</a></h2><p>Blend Mode 回答的是：<strong>当前片元的输出怎样改变已经存在的目标颜色？</strong> 它与 Lighting Mode、Render After DOF 是不同的选择。</p><p>在本文讨论的常规表面材质中，Opaque 和 Masked 走不透明路径；<code>IsTranslucentBlendMode</code> 用于识别其余相关透明混合模式。Masked 是阈值裁剪：片元被丢弃或作为不透明表面保留，不表达连续半透明。</p><p>以下只列常见 RGB 混合关系，具体状态还会随目标 Pass 和着色路径变化。<code>S</code> 表示 Shader 输出的源颜色，<code>D</code> 表示目标颜色，<code>a</code> 表示源 alpha。</p><table tabindex="0"><thead><tr><th>Blend Mode</th><th>常见 RGB 合成</th><th>用途与注意点</th></tr></thead><tbody><tr><td>Translucent</td><td><code>S * a + D * (1 - a)</code></td><td>普通半透明；需要正确的前后顺序</td></tr><tr><td>Additive</td><td><code>S + D</code></td><td>光晕、火焰；Shader 可先把材质 Opacity 乘进 <code>S</code>，不能因硬件系数为 One 就认为 Opacity 无效</td></tr><tr><td>Modulate</td><td><code>S * D</code></td><td>背景滤色；只表达乘色，不独立增加反射高光</td></tr><tr><td>AlphaComposite</td><td><code>S + D * (1 - a)</code></td><td>预乘 alpha；源 RGB 已含相应权重，不应重复乘 alpha</td></tr><tr><td>AlphaHoldout</td><td><code>D * (1 - a)</code></td><td>衰减当前目标颜色，用于受支持的 holdout 合成；不是让不透明几何的深度消失</td></tr></tbody></table><p>纯加法层之间在理想线性累加下与顺序无关，但它们和普通 Alpha 混合层交错时仍可能有顺序差异。例如先加上的光晕会被后画的烟雾衰减，最后加上的则不会。</p><p><strong>Thin Translucent 是 Shading Model，不是上表中的另一个 Blend Mode。</strong> 它需要同时表达表面的加色贡献与背景的彩色透射，可抽象为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Final = SurfaceContribution + ColoredTransmittance * Background</span></span></code></pre></div><p>能够直接访问真实背景的路径可通过 Dual Source Blend 表达这类关系；Separate Translucency 路径则需要拆开保存相应贡献，见下文。Thin Translucent 通常配合 Translucent Blend Mode 和 Surface ForwardShading 使用。</p><p>普通 alpha、预乘 alpha 的计算示例见 <a href="./../图形学/透明渲染.html#alpha-blend-与绘制顺序">Alpha Blend 与绘制顺序</a>。</p><h2 id="_3-为什么要分成不同的半透明-pass" tabindex="-1">3. 为什么要分成不同的半透明 Pass <a class="header-anchor" href="#_3-为什么要分成不同的半透明-pass" aria-label="Permalink to &quot;3. 为什么要分成不同的半透明 Pass&quot;">​</a></h2><h3 id="景深决定什么时候合成" tabindex="-1">景深决定什么时候合成 <a class="header-anchor" href="#景深决定什么时候合成" aria-label="Permalink to &quot;景深决定什么时候合成&quot;">​</a></h3><p>如果半透明已经混进 SceneColor，后续景深会把它和背景一起处理。烟雾、特效是否应该被这次景深模糊，便成为划分透明 Pass 的一个依据。</p><p>UE 4.27 材质中的 <strong>Render After DOF</strong> 对应 <code>bEnableSeparateTranslucency</code>。允许 Separate Translucency 时，主要分为下面几类：</p><table tabindex="0"><thead><tr><th>类别</th><th>MeshPass</th><th>主要进入条件</th><th>目标与合成时机</th></tr></thead><tbody><tr><td>Standard</td><td><code>TranslucencyStandard</code></td><td>不启用 Render After DOF</td><td>通常直接写 SceneColor，参与后续景深；降分辨率路径可先写独立 RT 再立即合成</td></tr><tr><td>AfterDOF</td><td><code>TranslucencyAfterDOF</code></td><td>启用 Render After DOF，且具有颜色贡献</td><td>写独立 Color RT，在景深之后或其重组阶段合成</td></tr><tr><td>AfterDOFModulate</td><td><code>TranslucencyAfterDOFModulate</code></td><td>AfterDOF 中的 Modulate / DualBlend 乘色贡献</td><td>写独立 Modulate RT，与独立颜色一起合成</td></tr><tr><td>All</td><td><code>TranslucencyAll</code></td><td>不允许 AfterDOF 分离路径</td><td>合并到单一透明 Pass 中处理</td></tr></tbody></table><p>因此，三个 Pass 并不一定对应三组互不相交的物体。同一材质如果同时具有加色和乘色贡献，可以参与两个 Pass。纯 Modulate 则不需要向独立颜色 RT 写入加色贡献。</p><p><code>RenderTranslucency</code> 中可以把调度理解为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AllowTranslucencyAfterDOF() 为真：</span></span>
<span class="line"><span>    Standard -&gt; AfterDOF -&gt; AfterDOFModulate</span></span>
<span class="line"><span>否则：</span></span>
<span class="line"><span>    All</span></span></code></pre></div><p>这个分支判断的是当前视图与配置是否允许分离路径，不能只根据本帧是否看到了景深模糊来推断。材质开关、Separate Translucency 配置和后处理能力要一起看。</p><h3 id="采样背景与普通混合是两件事" tabindex="-1">采样背景与普通混合是两件事 <a class="header-anchor" href="#采样背景与普通混合是两件事" aria-label="Permalink to &quot;采样背景与普通混合是两件事&quot;">​</a></h3><p>普通 Alpha Blend 由混合单元读取目标颜色，不要求透明 Shader 自己采样 SceneColor。材质需要 SceneColor 采样时，相关路径通过 <code>AddCopySceneColorPass</code> 等准备副本，避免将同一资源同时作为普通采样纹理和正在写入的渲染目标。</p><p>折射还涉及 Distortion 等处理，不能把所有折射都理解成普通 Alpha Blend 中的一次 SceneColor 采样。SceneColor 副本只记录复制时已有的内容，也不会自动提供所有透明层的完整颜色与深度，因此不等于支持任意多层玻璃互相折射。</p><h2 id="_4-独立半透明缓冲到底存了什么" tabindex="-1">4. 独立半透明缓冲到底存了什么 <a class="header-anchor" href="#_4-独立半透明缓冲到底存了什么" aria-label="Permalink to &quot;4. 独立半透明缓冲到底存了什么&quot;">​</a></h2><h3 id="color-的-alpha-保存剩余透射率" tabindex="-1">Color 的 Alpha 保存剩余透射率 <a class="header-anchor" href="#color-的-alpha-保存剩余透射率" aria-label="Permalink to &quot;Color 的 Alpha 保存剩余透射率&quot;">​</a></h3><p>AfterDOF 不能预先把背景烘进自己的颜色，因为真正要合成的背景还需要做景深。它需要记录“透明层自身贡献多少颜色”和“背景还应保留多少”。</p><p>先只考虑普通 Translucent，记 <code>C</code> 为已累积的颜色贡献，<code>T</code> 为背景剩余透射率。按照从后往前的顺序处理每层：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始：C = 0，T = 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>新片元颜色为 S，alpha 为 a：</span></span>
<span class="line"><span>    C = S * a + C * (1 - a)</span></span>
<span class="line"><span>    T = T * (1 - a)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终：Final = C + Background * T</span></span></code></pre></div><p>因此，独立 Color RT 的 RGB 是已经混合过的颜色贡献，<strong>不是把所有原始颜色简单相加</strong>；Alpha 保存的是 <code>T</code>，也不是直觉中的累计不透明度 <code>1 - T</code>。</p><p>例如两层 alpha 分别为 0.2 和 0.4，背景剩余比例是 <code>0.8 * 0.6 = 0.48</code>。这与 <a href="./SceneCapture.html">SceneCapture</a> 中 Inv Opacity 的概念相通，但不同输出目标的 Alpha 含义仍需分别确认。</p><h3 id="为什么还要一张-modulate-rt" tabindex="-1">为什么还要一张 Modulate RT <a class="header-anchor" href="#为什么还要一张-modulate-rt" aria-label="Permalink to &quot;为什么还要一张 Modulate RT&quot;">​</a></h3><p>一个标量 <code>T</code> 只能同等衰减 RGB 三个通道，不能同时表达“红色透过 20%，绿色透过 70%，蓝色透过 20%”。滤色需要额外保存一个 RGB 乘数 <code>M</code>。</p><table tabindex="0"><thead><tr><th>项目</th><th>Separate Color</th><th>Separate Modulate</th></tr></thead><tbody><tr><td>保存内容</td><td>RGB 为颜色贡献 <code>C</code>，Alpha 为透射率 <code>T</code></td><td>RGB 为滤色乘数 <code>M</code></td></tr><tr><td>空缓冲的值</td><td><code>(0, 0, 0, 1)</code></td><td>RGB 为 <code>(1, 1, 1)</code></td></tr><tr><td>常见格式</td><td><code>PF_FloatRGBA</code></td><td><code>PF_FloatR11G11B10</code></td></tr><tr><td>对应默认纹理</td><td><code>BlackAlphaOneDummy</code></td><td><code>WhiteDummy</code></td></tr></tbody></table><p>这种布局中，加色从黑开始，透射率和滤色从 1 开始，空缓冲不会改变背景。不是任意一种 RT 都无法存这些信息，而是当前布局需要同时容纳 RGB 颜色、标量透射率和 RGB 滤色数据。</p><p><code>ComposeSeparateTranslucency.usf</code> 以及相应 DOF 重组路径的核心关系可以概括为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Final = Scene * Separate.a * Modulate.rgb + Separate.rgb</span></span>
<span class="line"><span>      = Scene * T * M + C</span></span></code></pre></div><p>普通半透明不贡献额外滤色时，<code>M = 1</code>。例如取 <code>T = 1</code>，背景墙颜色 <code>(1.0, 0.8, 0.6)</code>、滤色 <code>(0.2, 0.7, 0.2)</code>、表面高光 <code>(0.3, 0.3, 0.3)</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>背景滤色：Scene * M     = (0.2, 0.56, 0.12)</span></span>
<span class="line"><span>再加高光：Scene * M + C = (0.5, 0.86, 0.42)</span></span></code></pre></div><p>在这里讨论的 <strong>AfterDOF 分离路径</strong>中，Thin Translucent / DualBlend 材质可将同一网格分别提交给颜色和乘色 Pass。不能由此推导所有 Thin Translucent 在所有管线中都会绘制两遍。</p><p>两张 RT 解决的是贡献的存储与合成，并没有保存每个像素的完整透明层列表，所以 <strong>Separate Translucency 不是 OIT</strong>。不同 Pass 的贡献也不能靠一个物体级排序键恢复任意交错关系。</p><h2 id="_5-网格怎样进入这些-pass" tabindex="-1">5. 网格怎样进入这些 Pass <a class="header-anchor" href="#_5-网格怎样进入这些-pass" aria-label="Permalink to &quot;5. 网格怎样进入这些 Pass&quot;">​</a></h2><p>这一段要分清两个步骤：<strong>先确定网格属于哪些 Pass，再由对应的 Mesh Processor 构造绘制命令。</strong> 完整机制见 <a href="./渲染机制.html">渲染机制</a>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>材质属性</span></span>
<span class="line"><span>    -&gt; Material Relevance：声明需要哪些透明路径</span></span>
<span class="line"><span>    -&gt; SceneVisibility：将可见网格登记到对应 MeshPass</span></span>
<span class="line"><span>    -&gt; 对应的 FBasePassMeshProcessor：过滤并构建 DrawCommand</span></span>
<span class="line"><span>    -&gt; 按当前视图更新排序键</span></span>
<span class="line"><span>    -&gt; 排序与提交</span></span></code></pre></div><p>在允许分离的路径中，相关 Relevance 与 Pass 的对应关系是：</p><table tabindex="0"><thead><tr><th>Material Relevance</th><th>对应类别</th></tr></thead><tbody><tr><td><code>bNormalTranslucency</code></td><td>Standard</td></tr><tr><td><code>bSeparateTranslucency</code></td><td>AfterDOF 颜色</td></tr><tr><td><code>bSeparateTranslucencyModulate</code></td><td>AfterDOF 乘色</td></tr></tbody></table><p>这些信息由 <code>UMaterialInterface</code> 的材质 Relevance 计算路径结合 Blend Mode、<code>bEnableSeparateTranslucency</code>、DualBlend 等条件生成；不允许分离时则使用 All 路径。</p><p><code>SceneVisibility.cpp</code> 中，静态 Mesh 通过 <code>DrawCommandPacket.AddCommandsForMesh(..., EMeshPass::Translucency*)</code> 登记，动态 Mesh 通过 <code>PassMask.Set(...)</code> 标记所需 Pass。需要颜色和乘色两路的网格可以被登记到两个列表。旁边的 <code>TranslucentPrimCount.Add</code> 用于统计与判断是否需要渲染，不负责构造 DrawCommand。</p><p><code>FBasePassMeshProcessor</code> 在构造时已经确定自己的 <code>TranslucencyPassType</code>，因此 <code>TryAddMeshBatch</code> 中的 switch 主要回答“<strong>当前 Processor 是否接收这条 Mesh</strong>”，不能把它当成将网格分发给所有 Pass 的入口。对应注册入口包括 <code>RegisterTranslucencyStandardPass</code>、AfterDOF 和 AfterDOFModulate。</p><p>还要区分 <strong>静态 Mesh 数据</strong>与<strong>缓存好的 MeshDrawCommand</strong>。这里的半透明 MeshPass 没有启用 <code>CachedMeshCommands</code> 时，静态 Mesh 也会通过 <code>DynamicBuildRequests</code> 请求本帧构造命令；不能看到静态模型就认定其透明命令无需重建。</p><h2 id="_6-排序" tabindex="-1">6. 排序 <a class="header-anchor" href="#_6-排序" aria-label="Permalink to &quot;6. 排序&quot;">​</a></h2><h3 id="按绘制项排序-并非逐像素排序" tabindex="-1">按绘制项排序，并非逐像素排序 <a class="header-anchor" href="#按绘制项排序-并非逐像素排序" aria-label="Permalink to &quot;按绘制项排序，并非逐像素排序&quot;">​</a></h3><p>UE 4.27 常规光栅透明路径没有通用 OIT，也不自动对任意透明 Mesh 做逐三角形排序。每个透明 Pass 维护自己的绘制列表，各 Pass 之间不进行一次统一的全局深度排序。</p><p><code>UpdateTranslucentMeshSortKeys</code> 会结合当前 View 和 Primitive 信息更新排序键。64 位键可概括为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Priority (16 bit) | Distance (32 bit) | MeshIdInPrimitive (16 bit)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>字段</th><th>作用</th></tr></thead><tbody><tr><td>Priority</td><td>来自 <code>TranslucencySortPriority</code>；优先级越大通常越晚画，因此会覆盖较低优先级的透明贡献</td></tr><tr><td>Distance</td><td>根据当前相机、Primitive Bounds 中心和排序策略生成；相同优先级下，通常让远处先画</td></tr><tr><td>MeshIdInPrimitive</td><td>用于同一 Primitive 内绘制项的稳定次序，不代表真实的逐三角形深度</td></tr></tbody></table><p>Priority 和 MeshId 在建立排序键时提供，Distance 随视图更新。这里不应把前两者笼统称为“缓存阶段设置”，因为透明命令本身可能就在本帧重建。</p><p><code>r.TranslucentSortPolicy</code> 对应的常见策略为：</p><table tabindex="0"><thead><tr><th>值</th><th>策略</th><th>排序依据</th></tr></thead><tbody><tr><td>0</td><td>SortByDistance</td><td>相机到 Bounds 中心的距离，常见于 3D 场景</td></tr><tr><td>1</td><td>SortByProjectedZ</td><td>沿相机观察方向的投影深度</td></tr><tr><td>2</td><td>SortAlongAxis</td><td>沿配置轴的投影，适合固定排序方向的场景</td></tr></tbody></table><p><code>TranslucencySortDistanceOffset</code> 可以偏移排序用的距离，但不移动几何，也不改变其真实深度。Priority 和 Offset 都只是在调整提交顺序。</p><h3 id="交叉为什么仍然会错" tabindex="-1">交叉为什么仍然会错 <a class="header-anchor" href="#交叉为什么仍然会错" aria-label="Permalink to &quot;交叉为什么仍然会错&quot;">​</a></h3><p>一个大玻璃面片可能在屏幕左侧位于另一个物体前面，右侧却位于它后面。Bounds 中心只提供一个排序值，无法同时满足这两个像素的要求。拆分成多个 Section 也不自动获得正确的逐三角形深度排序。</p><p>Niagara / Cascade 可以在系统内部进行粒子排序，但系统内部的顺序不能自动解决粒子与外部透明网格之间的交叉。同样，AfterDOF 与 Standard 已分属不同合成阶段，提高 Sort Priority 不会让它们重新加入同一份全局排序列表。</p><p>工程上可以按问题性质选择：</p><table tabindex="0"><thead><tr><th>情况</th><th>可考虑的处理</th><th>限制</th></tr></thead><tbody><tr><td>前后层次固定的特效</td><td>Priority 或 Distance Offset</td><td>是针对固定关系的控制，不解决局部前后关系反转</td></tr><tr><td>少量相交的静态玻璃</td><td>沿实际交叉关系拆分几何，再组织绘制</td><td>随意拆成几个子网格不保证正确</td></tr><tr><td>适合纯加光的效果</td><td>Additive</td><td>会改变视觉模型，与其他 Alpha 层交错时仍需关注顺序</td></tr><tr><td>主要是镂空轮廓</td><td>Masked，或适用时用 Dithered Opacity Mask</td><td>抖动依赖时域积累，可能有噪点和拖影，不等于玻璃透射</td></tr><tr><td>粒子插进不透明地面</td><td>材质 DepthFade</td><td>柔化交线，不解决透明层之间的排序</td></tr><tr><td>必须准确保留复杂交叉层次</td><td>评估自定义 OIT / 其他专用渲染路径</td><td>需要额外实现与性能预算，不是上述排序参数能做到的</td></tr></tbody></table><p>交叉示意、Depth Peeling、逐像素链表和 Weighted Blended OIT 的原理与取舍见 <a href="./../图形学/透明渲染.html#透明物体交叉如何处理">透明物体交叉如何处理</a>。DepthFade 对应的通用思路见 <a href="./../图形学/透明渲染.html#交叉处的硬边soft-particles">Soft Particles</a>。</p><h2 id="_7-半透明的光照从哪里来" tabindex="-1">7. 半透明的光照从哪里来 <a class="header-anchor" href="#_7-半透明的光照从哪里来" aria-label="Permalink to &quot;7. 半透明的光照从哪里来&quot;">​</a></h2><p>“走前向透明 Pass”意味着透明片元用自己的材质完成着色，并不意味着每种透明材质都会逐像素重新遍历所有灯。UE 提供不同的 Translucency Lighting Mode，以适配烟雾、表面玻璃等不同需求。</p><h3 id="translucency-lighting-volume" tabindex="-1">Translucency Lighting Volume <a class="header-anchor" href="#translucency-lighting-volume" aria-label="Permalink to &quot;Translucency Lighting Volume&quot;">​</a></h3><p>常见体积光照路径先在灯光阶段通过 <code>InjectTranslucentVolumeLighting</code> 等处理把光照注入相机附近的 3D 纹理，再由透明 Shader 通过 <code>GetTranslucencyVolumeLighting</code> 等函数采样。</p><p>它使用 Inner / Outer 两级覆盖范围，每级保存 Ambient / Directional 等光照信息；常见默认维度为 <code>64^3</code>，可由 <code>r.TranslucencyLightingVolumeDim</code> 等配置调整。有限分辨率意味着细小光照与阴影会变模糊，覆盖范围越大，同样分辨率下的空间精度越低。维度翻倍时，每张体积纹理的体素数量约变为八倍。</p><h3 id="lighting-mode-的区别" tabindex="-1">Lighting Mode 的区别 <a class="header-anchor" href="#lighting-mode-的区别" aria-label="Permalink to &quot;Lighting Mode 的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Lighting Mode</th><th>光照方式与适用情况</th></tr></thead><tbody><tr><td>Volumetric NonDirectional</td><td>体积光照，不使用材质法线表达方向变化，适合较均匀的烟尘</td></tr><tr><td>Volumetric Directional</td><td>利用方向性光照和法线表达变化，适合需要立体感的体积效果</td></tr><tr><td>Volumetric PerVertex 系列</td><td>在顶点阶段求相关光照，再插值给像素；通常减少像素开销，但受网格密度影响</td></tr><tr><td>Surface TranslucencyVolume</td><td>以表面材质方式使用低分辨率体积光照；直接光主要是漫反射，不能期待清晰的逐像素局部灯高光</td></tr><tr><td>Surface ForwardShading</td><td>在表面逐像素计算前向直接光照，可得到局部灯高光；灯数、覆盖面积和重叠层数都会影响成本</td></tr></tbody></table><p>Surface TranslucencyVolume 的限制不等于材质只能输出漫反射颜色；环境反射、自发光等仍需看相应材质与渲染路径。Thin Translucent 要表现表面高光和有色透射时，通常使用 Surface ForwardShading。</p><h2 id="_8-遇到问题时先检查哪一层" tabindex="-1">8. 遇到问题时先检查哪一层 <a class="header-anchor" href="#_8-遇到问题时先检查哪一层" aria-label="Permalink to &quot;8. 遇到问题时先检查哪一层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>优先检查</th></tr></thead><tbody><tr><td>透明物体和背景一起被景深模糊</td><td>Render After DOF、Separate Translucency 是否生效，以及实际合成位置</td></tr><tr><td>调高排序优先级也没有达到预期遮挡关系</td><td>两者是否属于不同 Pass，或是否存在局部交叉</td></tr><tr><td>玻璃缺少清晰的局部灯高光</td><td>Lighting Mode 是否仍为 Surface TranslucencyVolume</td></tr><tr><td>染色玻璃只有亮度变化，没有分通道滤色</td><td>是否需要 Thin Translucent，以及对应颜色 / 乘色路径是否启用</td></tr><tr><td>粒子与地面相交出现硬边</td><td>DepthFade 以及可采样场景深度是否符合预期</td></tr><tr><td>透明物体穿墙显示</td><td>Disable Depth Test 或其他覆盖了深度状态的设置</td></tr><tr><td>半透明开销高</td><td>屏幕覆盖率、重叠层数、Shader 与光照复杂度，以及独立 RT 的分辨率和额外 Pass</td></tr></tbody></table><p>拆到独立 RT 并不自动降低成本。低分辨率渲染可以节省部分像素开销，但还要支付 RT、采样、上采样和合成成本，也可能损失边缘与细节质量。</p><h2 id="_9-源码阅读入口与相关笔记" tabindex="-1">9. 源码阅读入口与相关笔记 <a class="header-anchor" href="#_9-源码阅读入口与相关笔记" aria-label="Permalink to &quot;9. 源码阅读入口与相关笔记&quot;">​</a></h2><p>以下符号与文件用于定位 UE 4.27 对应实现，具体分支条件需要结合视图配置、材质排列和平台支持阅读。</p><table tabindex="0"><thead><tr><th>文件</th><th>重点查看的职责</th></tr></thead><tbody><tr><td><code>DeferredShadingRenderer.cpp</code></td><td>半透明在整帧中的调度位置与特殊路径</td></tr><tr><td><code>TranslucentRendering.cpp</code></td><td><code>RenderTranslucency</code>、独立 RT、SceneColorCopy、合成安排</td></tr><tr><td><code>SceneVisibility.cpp</code></td><td>Relevance、<code>AddCommandsForMesh</code>、动态 <code>PassMask</code></td></tr><tr><td><code>BasePassRendering.cpp</code></td><td>Processor 注册、<code>TryAddMeshBatch</code> 过滤、Blend / Depth 状态、初始排序键</td></tr><tr><td><code>MeshDrawCommands.cpp</code></td><td><code>UpdateTranslucentMeshSortKeys</code> 与绘制命令排序</td></tr><tr><td><code>TranslucentLighting.cpp</code></td><td>半透明光照体积的清理、注入与滤波</td></tr><tr><td><code>BasePassPixelShader.usf</code></td><td>透明材质着色、体积光照与混合模式对应的输出</td></tr><tr><td><code>ComposeSeparateTranslucency.usf</code></td><td>独立颜色、透射率与滤色的合成</td></tr><tr><td><code>PostProcessing.cpp</code> / <code>DiaphragmDOF</code> 相关实现</td><td>Separate Translucency 的合成位置与景深重组</td></tr><tr><td><code>MobileTranslucentRendering.cpp</code> / <code>RayTracingTranslucency.cpp</code></td><td>本文主路径之外的 Mobile / 光线追踪实现</td></tr></tbody></table><p>相关笔记：</p><ul><li><a href="./../图形学/透明渲染.html">透明渲染</a>：通用混合公式、深度状态、交叉处理和 OIT。</li><li><a href="./../图形学/延迟渲染.html">延迟渲染</a>：GBuffer 与混合渲染管线。</li><li><a href="./渲染机制.html">渲染机制</a>：MeshPass、Mesh Processor 与 DrawCommand 的完整关系。</li><li><a href="./材质.html">材质</a> / <a href="./UE_材质到Shader处理机制.html">UE_材质到Shader处理机制</a>：材质属性与 Shader 路径。</li><li><a href="./粒子系统/Cascade.html">粒子系统/Cascade</a>：粒子系统相关背景。</li></ul>`,90)])])}const b=e(n,[["render",r]]);export{u as __pageData,b as default};
